public class MethodInvokerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object call(Object target, String name, Object... args) {
        try {
            return MethodInvoker.call(target, name, args);
        } catch (Throwable t) {
            return t.getClass().getSimpleName() + ": " + t.getMessage();
        }
    }

    public static void main(String[] args) {
        TextTools tools = new TextTools();

        check("a private one-argument method", "HEY", call(tools, "shout", "hey"));
        check("two int arguments are unboxed by invoke", 7, call(tools, "addUp", 2, 5));
        check("mixed argument types", "ababab", call(tools, "repeat", "ab", 3));
        check("a no-argument method", "hi", call(tools, "greet"));
        check("zero repeats", "", call(tools, "repeat", "x", 0));
        check("a name that does not exist", "NoSuchMethodException: missing",
                call(tools, "missing"));
        check("the right name with the wrong argument count",
                "NoSuchMethodException: shout", call(tools, "shout"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

